class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:
        MOD = 10**9 + 7
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(rem, face, run):
            if rem == 0:
                return 1
            total = 0
            for f in range(6):
                if f == face:
                    if run < rollMax[face]:
                        total += dfs(rem - 1, f, run + 1)
                else:
                    total += dfs(rem - 1, f, 1)
            return total % MOD

        ans = 0
        for f in range(6):
            ans += dfs(n - 1, f, 1)
        return ans % MOD

