class Solution {
public:
    int dieSimulator(int n, vector<int>& rollMax) {
        const int MOD = 1e9 + 7;
        static int memo[5001][6][16];
        memset(memo, -1, sizeof(memo));
        function<int(int,int,int)> dfs = [&](int rem, int face, int run) -> int {
            if (rem == 0) return 1;
            int &res = memo[rem][face][run];
            if (res != -1) return res;
            long long total = 0;
            for (int f = 0; f < 6; ++f) {
                if (f == face) {
                    if (run < rollMax[face])
                        total += dfs(rem - 1, f, run + 1);
                } else {
                    total += dfs(rem - 1, f, 1);
                }
            }
            return res = total % MOD;
        };
        long long ans = 0;
        for (int f = 0; f < 6; ++f) ans += dfs(n - 1, f, 1);
        return ans % MOD;
    }
};

