class Solution {
    private int[][][] memo;
    private int[] rollMax;
    private static final int MOD = 1_000_000_007;

    public int dieSimulator(int n, int[] rollMax) {
        this.rollMax = rollMax;
        memo = new int[n + 1][6][16];
        for (int[][] a : memo)
            for (int[] b : a)
                java.util.Arrays.fill(b, -1);
        long ans = 0;
        for (int f = 0; f < 6; f++) ans += dfs(n - 1, f, 1);
        return (int) (ans % MOD);
    }

    private int dfs(int rem, int face, int run) {
        if (rem == 0) return 1;
        if (memo[rem][face][run] != -1) return memo[rem][face][run];
        long total = 0;
        for (int f = 0; f < 6; f++) {
            if (f == face) {
                if (run < rollMax[face]) total += dfs(rem - 1, f, run + 1);
            } else {
                total += dfs(rem - 1, f, 1);
            }
        }
        return memo[rem][face][run] = (int) (total % MOD);
    }
}

