                total += dfs(rem - 1, f, 1);
            }
        }
        const v = total % MOD;
        memo.set(k, v);
        return v;
    }
    let ans = 0;
    for (let f = 0; f < 6; f++) ans += dfs(n - 1, f, 1);
    return ans % MOD;
