class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:
        MOD = 10**9 + 7
        dp = [[0] * 16 for _ in range(6)]
        for f in range(6):
            dp[f][1] = 1
        for _ in range(n - 1):
            ndp = [[0] * 16 for _ in range(6)]
            for f in range(6):
                s = sum(dp[g][r] for g in range(6) for r in range(1, rollMax[g] + 1))
                for r in range(1, rollMax[f] + 1):
                    v = dp[f][r]
                    if not v:
                        continue
                    if r < rollMax[f]:
                        ndp[f][r + 1] = (ndp[f][r + 1] + v) % MOD
                    ndp[f][1] = (ndp[f][1] + s - v) % MOD
            dp = ndp
        return sum(dp[f][r] for f in range(6) for r in range(16)) % MOD

