class Solution {
public:
    int dieSimulator(int n, vector<int>& rollMax) {
        const int MOD = 1e9 + 7;
        vector<vector<long long>> dp(6, vector<long long>(16, 0));
        for (int f = 0; f < 6; ++f) dp[f][1] = 1;
        for (int step = 1; step < n; ++step) {
            vector<vector<long long>> ndp(6, vector<long long>(16, 0));
            for (int f = 0; f < 6; ++f) {
                long long s = 0;
                for (int g = 0; g < 6; ++g)
                    for (int r = 1; r <= rollMax[g]; ++r)
                        s += dp[g][r];
                for (int r = 1; r <= rollMax[f]; ++r) {
                    long long v = dp[f][r];
                    if (!v) continue;
                    if (r < rollMax[f]) ndp[f][r + 1] = (ndp[f][r + 1] + v) % MOD;
                    ndp[f][1] = (ndp[f][1] + s - v) % MOD;
                }
            }
            dp = move(ndp);
        }
        long long ans = 0;
        for (int f = 0; f < 6; ++f)
            for (int r = 0; r < 16; ++r) ans += dp[f][r];
        return ans % MOD;
    }
};

